func ptrQueuedMessage(p unsafe.Pointer, c int32) any {
	r := (*conversationqueue.QueuedMessage)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ThreadID))
	case 4:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 5:
		return &r.Content
	case 6:
		return &r.Request
	case 7:
		return &r.Position
	case 8:
		return &r.Steer
	case 9:
		return &r.Version
	case 10:
		return &r.CreatedAt
	case 11:
		return &r.UpdatedAt
	}
	return nil
}

func valueQueuedMessage(p unsafe.Pointer, c int32) any {
	r := (*conversationqueue.QueuedMessage)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.ThreadID)
	case 4:
		return string(r.UserID)
	case 5:
		return r.Content
	case 6:
		if r.Request == nil {
			return nil
		}
		return *r.Request
	case 7:
		return r.Position
	case 8:
		return r.Steer
	case 9:
		return r.Version
	case 10:
		return r.CreatedAt
	case 11:
		return r.UpdatedAt
	}
	return nil
}

func attachQueuedMessage(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*conversationqueue.QueuedMessage)(p)
	switch rel {
	case 0:
		r.User = (*tenant.User)(child)
	case 1:
		r.Thread = (*conversation.Thread)(child)
	}
}

func init() {
	queuedMessagesTable.Relations[0].Target = tenantdb.UsersSchema()
	queuedMessagesTable.Relations[1].Target = conversationdb.ThreadsSchema()
}
